function localData(
  response: unknown,
  _options: { payload: Record<string, unknown> }
): ListLoadResult {
  // \u6D4B\u8BD5\u6570\u636E
  // eslint-disable-next-line
  response = mockResult
  const r = response as {
    code?: string
    message?: string
    data?: { list?: unknown; totalPage?: number }
  }
  if (r.code === '1') {
    return {
      status: 'success',
      code: r.code,
      data: {
        list: r.data?.list as ListAsyncItem[] | undefined,
        totalPage: r.data?.totalPage
      }
    }
  }
  return {
    status: 'error',
    code: r.code,
    message: r.message
  }
}

export default localData
